});

// Parse the response JSON and the sent request payload
const responseData = pm.response.json();
const sentPayload = JSON.parse(pm.request.body.raw);

// Retrieve the expected ID from your environment variable
const expectedId = Number(pm.variables.get("id"));

// 1. Validate: The returned ID should be the same as the ID stored in the variable
pm.test("Returned ID matches the stored ID variable", function () {
    pm.expect(responseData.id).to.eql(expectedId);
});

// 2. Validate: Phone should not be empty
pm.test("Phone is not empty", function () {
    pm.expect(responseData.phone).to.exist;
    pm.expect(String(responseData.phone).trim()).to.not.be.empty;
});

// 3. Validate: Returned name should match the updated name
pm.test("Returned name matches the updated name", function () {
    pm.expect(responseData.name).to.eql(sentPayload.name);
});

